import {emptyProject} from './templates.js';
export const TIVA_EXAMPLES=[{id:'lcd8p',name:'Tiva C · LCD 8×2 paralel',detail:'C17 · cf_lcd.h · modülsüz'},{id:'lcd16p',name:'Tiva C · LCD 16×2 paralel',detail:'C17 · 4-bit GPIO · modülsüz'},{id:'lcd8',name:'Tiva C · LCD 8×2 I²C',detail:'C17 · PCF8574 · 0x27 · yazılımsal I²C'},{id:'blink',name:'Tiva C · RGB LED ve UART',detail:'C17 · otomatik GPIO/UART kütüphaneleri'},{id:'buttons',name:'Tiva C · SW1 / SW2',detail:'PF4 / PF0 kilit açma ve pull-up'},{id:'timer',name:'Tiva C · Timer0A kesmesi',detail:'Gerçek ARM IRQ19 / vektör35'},{id:'adc',name:'Tiva C · PE3 analog giriş',detail:'Potansiyometre · ADC0 SS3 / AIN0'}];
const lcdSource=(columns,i2c)=>`#include <cf_lcd.h>\nint main(void) {\n    ${i2c?'if (!cf_lcd_i2c_init(PB2, PB3, 0x27, '+columns+')) while(1) {}':'cf_lcd_init(PA2, PA3, PB0, PB1, PE4, PE5, '+columns+');'}\n    cf_lcd_print("${columns===8?'Tiva C':'Tiva C LaunchPad'}");\n    cf_lcd_cursor(0,1); cf_lcd_print("${i2c?'I2C OK':columns===8?'8x2 OK':'16x2 parallel'}");\n    cf_gpio_mode(PF3,CF_OUTPUT); cf_gpio_write(PF3,1);\n    while(1) {}\n}\n`;
export const TIVA_SOURCES={lcd8p:lcdSource(8,false),lcd16p:lcdSource(16,false),lcd8:lcdSource(8,true),
 blink:`#include <stdint.h>\n#include <stdbool.h>\n#include "inc/hw_memmap.h"\n#include "driverlib/sysctl.h"\n#include "driverlib/gpio.h"\n#include <cf_hal.h>\n#include <stdio.h>\n\nint main(void) {\n    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOF);\n    while (!SysCtlPeripheralReady(SYSCTL_PERIPH_GPIOF)) {}\n    GPIOPinTypeGPIOOutput(GPIO_PORTF_BASE, GPIO_PIN_1 | GPIO_PIN_2 | GPIO_PIN_3);\n    cf_uart_begin(115200);\n    puts("Tiva C LaunchPad / C17 hazir");\n    const uint8_t colors[] = {GPIO_PIN_1, GPIO_PIN_3, GPIO_PIN_2};\n    while (1) {\n        for (unsigned i=0; i<3; ++i) {\n            GPIOPinWrite(GPIO_PORTF_BASE, 14, colors[i]);\n            printf("RGB %u\\r\\n", i);\n            cf_delay_ms(100);\n        }\n    }\n}\n`,
 buttons:`#include <cf_hal.h>\n#include <stdio.h>\nint main(void) {\n    cf_gpio_mode(PF1, CF_OUTPUT); cf_gpio_mode(PF2, CF_OUTPUT);\n    cf_gpio_mode(PF4, CF_INPUT_PULLUP);\n    cf_gpio_mode(PF0, CF_INPUT_PULLUP); /* CF HAL unlocks PF0 commit register. */\n    cf_uart_begin(115200); puts("SW1 / SW2 hazir");\n    while (1) {\n        cf_gpio_write(PF1, !cf_gpio_read(PF4));\n        cf_gpio_write(PF2, !cf_gpio_read(PF0));\n    }\n}\n`,
 timer:`#include <cf_hal.h>\nvolatile unsigned ticks;\nvoid Timer0A_Handler(void) {\n    TimerIntClear(TIMER0_BASE, TIMER_TIMA_TIMEOUT);\n    cf_gpio_write(PF3, (++ticks)&1);\n}\nint main(void) {\n    cf_gpio_mode(PF3, CF_OUTPUT);\n    SysCtlPeripheralEnable(SYSCTL_PERIPH_TIMER0);\n    TimerConfigure(TIMER0_BASE, TIMER_CFG_PERIODIC);\n    TimerLoadSet(TIMER0_BASE, TIMER_A, SysCtlClockGet()/100-1);\n    TimerIntEnable(TIMER0_BASE, TIMER_TIMA_TIMEOUT);\n    IntEnable(INT_TIMER0A); IntMasterEnable();\n    TimerEnable(TIMER0_BASE, TIMER_A);\n    while (1) { __asm__ volatile("wfi"); }\n}\n`,
 adc:`#include <cf_hal.h>\n#include <stdio.h>\nint main(void) {\n    cf_uart_begin(115200);\n    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOE);\n    SysCtlPeripheralEnable(SYSCTL_PERIPH_ADC0);\n    GPIOPinTypeADC(GPIO_PORTE_BASE, GPIO_PIN_3);\n    ADCSequenceConfigure(ADC0_BASE,3,ADC_TRIGGER_PROCESSOR,0);\n    ADCSequenceStepConfigure(ADC0_BASE,3,0,ADC_CTL_CH0|ADC_CTL_IE|ADC_CTL_END);\n    ADCSequenceEnable(ADC0_BASE,3);\n    while(1) {\n        uint32_t n; ADCIntClear(ADC0_BASE,3); ADCProcessorTrigger(ADC0_BASE,3);\n        while(!ADCIntStatus(ADC0_BASE,3,false)){}\n        ADCSequenceDataGet(ADC0_BASE,3,&n); printf("ADC=%u\\r\\n",n);\n        cf_delay_ms(50);\n    }\n}\n`
};
export function createTivaProject({name='Tiva C LaunchPad',language='c',starter='blink'}={}){if(language!=='c')throw Error('Tiva LaunchPad yalnız C17 destekler.');if(!['empty',...TIVA_EXAMPLES.map(e=>e.id)].includes(starter))throw Error('Tiva örneği desteklenmiyor.');const p=emptyProject();p.name=name;p.language='c';p.code=TIVA_SOURCES[starter]||'#include <cf_hal.h>\nint main(void) { while(1) {} }\n';p.settings.probe='PF1';p.settings.tracePins=['PF2','PF3','PF4'];p.components=[{id:'mcu',type:'board',x:35,y:65,rotation:0,params:{model:'ek-tm4c123gxl'}},{id:'bb1',type:'breadboard',x:430,y:150,rotation:0,params:{}}];p.wires=[];if(starter==='adc'){p.components.push({id:'pot1',type:'pot',x:500,y:350,rotation:0,params:{value:50,ohms:10000}});p.wires=[['mcu:3V3','pot1:VCC'],['mcu:GND','pot1:GND'],['mcu:PE3','pot1:OUT']].map(([from,to],i)=>({id:'tiva-w'+i,from,to,color:'#14b8a6',points:[]}));p.settings.probe='PE3';}if(['lcd8p','lcd16p','lcd8'].includes(starter)){p.components=p.components.filter(c=>c.type!=='breadboard');p.components.push({id:'lcd',type:starter,x:420,y:90,rotation:0,params:starter==='lcd8'?{address:39}:{}});const links=starter==='lcd8'?[['3V3','VCC'],['GND','GND'],['PB2','SDA'],['PB3','SCL']]:[['3V3','VCC'],['GND','GND'],['GND','VO'],['GND','RW'],['3V3','A'],['GND','K'],['PA2','RS'],['PA3','E'],['PB0','D4'],['PB1','D5'],['PE4','D6'],['PE5','D7']];p.wires=links.map(([a,b],i)=>({id:'lcd-w'+i,from:'mcu:'+a,to:'lcd:'+b,color:a==='GND'?'#64748b':a==='3V3'?'#ef4444':'#14b8a6',points:[]}));}return p;}
